"""Temporal reconstruction of daily gridded climate datasets."""

from __future__ import annotations

import datetime
import math
import re
from typing import Any

_SCHEMA = "climate-grid/temporal-v1"
_DATASET_SCHEMA = "climate-grid/dataset-v1"
_IDW_SCHEMA = "climate-grid/idw-v1"
_FRAME_KEYS = frozenset({"time", "dataset"})
_DATASET_KEYS = frozenset({"schema", "data"})
_GRID_KEYS = frozenset({"schema", "lats", "lons", "values", "counts"})
_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")


def _round_output(value: float) -> float:
    value = round(value, 12)
    if value == 0.0:
        # Normalize negative zero.
        return 0.0
    return value


def _parse_date(value: Any, where: str) -> datetime.date:
    if not isinstance(value, str):
        raise TypeError(f"{where}.time must be a str")
    if _DATE_RE.fullmatch(value) is None:
        raise ValueError(f"{where}.time must be a YYYY-MM-DD date")
    year, month, day = (int(part) for part in value.split("-"))
    try:
        return datetime.date(year, month, day)
    except ValueError:
        raise ValueError(f"{where}.time must be a valid Gregorian date") from None


def _validate_axis(axis: Any, name: str) -> None:
    if not isinstance(axis, list):
        raise TypeError(f"{name} must be a list")
    if len(axis) == 0:
        raise ValueError(f"{name} must be non-empty")
    for index, value in enumerate(axis):
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError(
                f"{name}[{index}] must be a finite non-bool int or float"
            )
        if not math.isfinite(value):
            raise ValueError(f"{name}[{index}] must be finite")
    for index in range(1, len(axis)):
        if axis[index] <= axis[index - 1]:
            raise ValueError(f"{name} must be strictly increasing")


def _validate_matrix(
    matrix: Any, n_lat: int, n_lon: int, name: str, *, counts: bool
) -> None:
    if not isinstance(matrix, list):
        raise TypeError(f"{name} must be a list")
    if len(matrix) != n_lat:
        raise ValueError(f"{name} must have {n_lat} rows (one per lat)")

    for row_index, row in enumerate(matrix):
        where = f"{name}[{row_index}]"
        if not isinstance(row, list):
            raise TypeError(f"{where} must be a list")
        if len(row) != n_lon:
            raise ValueError(f"{where} must have {n_lon} cells (one per lon)")

        for cell_index, cell in enumerate(row):
            target = f"{where}[{cell_index}]"
            if counts:
                if not isinstance(cell, int) or isinstance(cell, bool):
                    raise TypeError(f"{target} must be a non-bool int")
                if cell < 0:
                    raise ValueError(f"{target} must be non-negative")
            elif cell is not None:
                if not isinstance(cell, (int, float)) or isinstance(cell, bool):
                    raise TypeError(f"{target} must be a number or None")
                if not math.isfinite(cell):
                    raise ValueError(f"{target} must be finite")


def _validate_grid(grid: Any, where: str) -> tuple[list, list, list]:
    if not isinstance(grid, dict):
        raise TypeError(f"{where} must be a dict")
    if set(grid.keys()) != _GRID_KEYS:
        raise ValueError(
            f"{where} must have exactly the keys schema, lats, lons, values, counts"
        )
    if not isinstance(grid["schema"], str):
        raise TypeError(f"{where}.schema must be a str")
    if grid["schema"] != _IDW_SCHEMA:
        raise ValueError(f"{where}.schema must be {_IDW_SCHEMA!r}")

    lats = grid["lats"]
    lons = grid["lons"]
    _validate_axis(lats, f"{where}.lats")
    _validate_axis(lons, f"{where}.lons")

    _validate_matrix(
        grid["values"], len(lats), len(lons), f"{where}.values", counts=False
    )
    _validate_matrix(
        grid["counts"], len(lats), len(lons), f"{where}.counts", counts=True
    )

    return lats, lons, grid["values"]


def _validate_dataset(
    dataset: Any, frame_index: int
) -> tuple[list[str], dict[str, tuple[list, list, list]]]:
    where = f"frames[{frame_index}].dataset"
    if not isinstance(dataset, dict):
        raise TypeError(f"{where} must be a dict")
    if set(dataset.keys()) != _DATASET_KEYS:
        raise ValueError(f"{where} must have exactly the keys schema, data")
    if not isinstance(dataset["schema"], str):
        raise TypeError(f"{where}.schema must be a str")
    if dataset["schema"] != _DATASET_SCHEMA:
        raise ValueError(f"{where}.schema must be {_DATASET_SCHEMA!r}")

    data = dataset["data"]
    if not isinstance(data, dict):
        raise TypeError(f"{where}.data must be a dict")
    if len(data) == 0:
        raise ValueError(f"{where}.data must be non-empty")

    order: list[str] = []
    grids: dict[str, tuple[list, list, list]] = {}
    for element, grid in data.items():
        if not isinstance(element, str):
            raise TypeError(f"{where}.data element names must be str")
        if element == "":
            raise ValueError(f"{where}.data element names must be non-empty")
        order.append(element)
        grids[element] = _validate_grid(grid, f"{where}.data[{element!r}]")

    ref_lats, ref_lons, _ = grids[order[0]]
    for element in order[1:]:
        lats, lons, _ = grids[element]
        if lats != ref_lats or lons != ref_lons:
            raise ValueError(
                f"lats/lons for element {element!r} must match within a frame"
            )

    return order, grids


def reconstruct(frames, *, max_gap: int = 2) -> dict:
    """Reconstruct a gap-filled daily time series of gridded datasets.

    Each frame is a dict with exactly the keys ``time`` and ``dataset``:
    ``time`` is a unique, strictly formatted Gregorian ``YYYY-MM-DD`` str and
    ``dataset`` is a complete :func:`climate_grid.dataset.build` result
    (schema ``climate-grid/dataset-v1``), whose per-element values are
    complete :func:`climate_grid.interpolation.idw_grid` results.  Frames may
    be given out of order, but every frame must contain the same elements in
    the same order, and each element's ``lats``/``lons`` must be identical
    within and across frames.

    The output time axis spans the earliest through the latest frame date,
    one entry per calendar day in ascending order; days without a frame are
    treated as all-``None``.  For every element and grid cell, known values
    are kept as ``observed``.  A consecutive run of missing values is
    ``interpolated`` by linear interpolation against calendar date only when
    known values bound the run on both sides and the distance in days between
    those bounding values is at most ``max_gap`` (a non-bool non-negative
    int); otherwise the run stays ``missing``, as do un-bounded runs at
    either end of the axis.

    The returned mapping uses the key order ``schema, times, lats, lons,
    data``; ``schema`` is ``climate-grid/temporal-v1`` and ``times`` is the
    list of ``YYYY-MM-DD`` strings.  ``data`` follows the first frame's
    element order and each item uses the key order ``values, status,
    uncertainty``; the three members are nested ``[time][lat][lon]``.
    Status is one of ``observed``, ``interpolated`` or ``missing``, and
    uncertainty is ``0.0`` for observed values, half the absolute difference
    of the two bounding values for interpolated values, and ``None`` for
    missing values.  Every output number (including known values and the
    shared ``lats``/``lons``) is ``round(x, 12)`` with negative zero
    normalized to ``0.0``.  Inputs are not modified.

    Raises ``TypeError`` for wrong container/item/argument types and
    ``ValueError`` for malformed dates, duplicate times, bad schemas or
    grids, empty frames, invalid ``max_gap``, or elements/axes that are not
    consistent within or across frames.
    """
    if not isinstance(frames, list):
        raise TypeError("frames must be a list of frame dicts")
    if len(frames) == 0:
        raise ValueError("frames must be non-empty")

    # (date, element order, {element: (lats, lons, values)}) per input frame.
    parsed: list[tuple[datetime.date, list[str], dict]] = []
    seen_dates: set[datetime.date] = set()
    for index, frame in enumerate(frames):
        where = f"frames[{index}]"
        if not isinstance(frame, dict):
            raise TypeError(f"{where} must be a dict")
        if set(frame.keys()) != _FRAME_KEYS:
            raise ValueError(f"{where} must have exactly the keys time, dataset")

        day = _parse_date(frame["time"], where)
        if day in seen_dates:
            raise ValueError(f"duplicate frame time: {frame['time']!r}")
        seen_dates.add(day)

        order, grids = _validate_dataset(frame["dataset"], index)
        parsed.append((day, order, grids))

    if not isinstance(max_gap, int) or isinstance(max_gap, bool):
        raise TypeError("max_gap must be a non-bool int")
    if max_gap < 0:
        raise ValueError("max_gap must be non-negative")

    reference_order = parsed[0][1]
    reference_grids = parsed[0][2]
    for _, order, grids in parsed[1:]:
        if order != reference_order:
            raise ValueError(
                "all frames must contain the same elements in the same order"
            )
        for element in reference_order:
            ref_lats, ref_lons, _ = reference_grids[element]
            lats, lons, _ = grids[element]
            if lats != ref_lats or lons != ref_lons:
                raise ValueError(
                    f"lats/lons for element {element!r} must match across frames"
                )

    ordered = sorted(parsed, key=lambda item: item[0])
    start = ordered[0][0]
    end = ordered[-1][0]
    n_times = (end - start).days + 1
    times = [
        (start + datetime.timedelta(days=offset)).isoformat()
        for offset in range(n_times)
    ]
    # (day offset from start, grids) for each present frame, ascending.
    present = [((day - start).days, grids) for day, _, grids in ordered]

    first_element = reference_order[0]
    out_lats = [
        _round_output(value) for value in reference_grids[first_element][0]
    ]
    out_lons = [
        _round_output(value) for value in reference_grids[first_element][1]
    ]

    data: dict[str, dict] = {}
    for element in reference_order:
        ref_lats, ref_lons, _ = reference_grids[element]
        n_lat = len(ref_lats)
        n_lon = len(ref_lons)
        values = [
            [[None for _ in range(n_lon)] for _ in range(n_lat)]
            for _ in range(n_times)
        ]
        status = [
            [[None for _ in range(n_lon)] for _ in range(n_lat)]
            for _ in range(n_times)
        ]
        uncertainty = [
            [[None for _ in range(n_lon)] for _ in range(n_lat)]
            for _ in range(n_times)
        ]

        for lat_index in range(n_lat):
            for lon_index in range(n_lon):
                # Known value per day offset; None means missing.
                series: list[float | None] = [None] * n_times
                for offset, grids in present:
                    value = grids[element][2][lat_index][lon_index]
                    if value is not None:
                        series[offset] = value

                tick = 0
                while tick < n_times:
                    if series[tick] is not None:
                        values[tick][lat_index][lon_index] = _round_output(
                            series[tick]
                        )
                        status[tick][lat_index][lon_index] = "observed"
                        uncertainty[tick][lat_index][lon_index] = 0.0
                        tick += 1
                        continue

                    # Run of consecutive missing values [tick, run_end).
                    run_end = tick
                    while run_end < n_times and series[run_end] is None:
                        run_end += 1
                    left = tick - 1
                    gap_days = run_end - left

                    if (
                        left >= 0
                        and run_end < n_times
                        and gap_days <= max_gap
                    ):
                        left_value = series[left]
                        right_value = series[run_end]
                        half_gap = _round_output(
                            abs(right_value - left_value) / 2.0
                        )
                        for missing in range(tick, run_end):
                            fraction = (missing - left) / gap_days
                            interpolated = (
                                left_value
                                + (right_value - left_value) * fraction
                            )
                            values[missing][lat_index][lon_index] = (
                                _round_output(interpolated)
                            )
                            status[missing][lat_index][lon_index] = (
                                "interpolated"
                            )
                            uncertainty[missing][lat_index][lon_index] = half_gap
                    else:
                        for missing in range(tick, run_end):
                            status[missing][lat_index][lon_index] = "missing"

                    tick = run_end

        data[element] = {
            "values": values,
            "status": status,
            "uncertainty": uncertainty,
        }

    return {
        "schema": _SCHEMA,
        "times": times,
        "lats": out_lats,
        "lons": out_lons,
        "data": data,
    }

"""Regional aggregation of reconstructed daily climate grids."""

from __future__ import annotations

import datetime
import math
import re
from bisect import bisect_right
from typing import Any

__all__ = [
    "aggregate",
    "aggregate_multi",
    "aggregate_window",
    "aggregate_weighted_window",
    "aggregate_weighted_change",
    "aggregate_weighted_exceedance",
    "aggregate_weighted_quantile",
    "aggregate_weighted_variance",
    "aggregate_variance",
    "aggregate_multi_variance",
    "aggregate_skewness",
    "aggregate_kurtosis",
    "aggregate_multi_kurtosis",
    "aggregate_multi_skew",
    "aggregate_coverage",
    "aggregate_multi_coverage",
    "aggregate_exceedance",
    "aggregate_multi_exceedance",
    "aggregate_quantile",
    "aggregate_histogram",
    "aggregate_entropy",
    "aggregate_weighted_histogram",
    "aggregate_weighted_entropy",
    "aggregate_multi_window",
    "aggregate_weighted_multi_window",
    "aggregate_weighted_multi_variance",
    "aggregate_trend",
    "aggregate_weighted_trend",
    "aggregate_correlation",
    "aggregate_multi_correlation",
    "aggregate_weighted_correlation",
    "aggregate_autocorrelation",
    "aggregate_weighted_autocorrelation",
    "aggregate_regression",
    "aggregate_weighted_regression",
    "aggregate_change",
    "aggregate_change_multi",
    "aggregate_weighted_change_multi",
    "aggregate_multi_autocorr",
    "aggregate_weighted_multi_autocorr",
    "aggregate_multi_quantile",
    "aggregate_weighted_multi_quantile",
    "aggregate_multi_entropy",
    "aggregate_weighted_multi_entropy",
]

_SCHEMA = "climate-grid/regional-v1"
_MULTI_SCHEMA = "climate-grid/regional-multi-v1"
_WINDOW_SCHEMA = "climate-grid/window-v1"
_WEIGHTED_WINDOW_SCHEMA = "climate-grid/weighted-window-v1"
_WEIGHTED_CHANGE_SCHEMA = "climate-grid/weighted-change-window-v1"
_WEIGHTED_EXCEEDANCE_SCHEMA = "climate-grid/weighted-exceedance-window-v1"
_WEIGHTED_QUANTILE_SCHEMA = "climate-grid/weighted-quantile-window-v1"
_WEIGHTED_VARIANCE_SCHEMA = "climate-grid/weighted-variance-window-v1"
_MULTI_WINDOW_SCHEMA = "climate-grid/multi-window-v1"
_WEIGHTED_MULTI_WINDOW_SCHEMA = "climate-grid/weighted-multi-window-v1"
_QUANTILE_SCHEMA = "climate-grid/quantile-window-v1"
_HISTOGRAM_SCHEMA = "climate-grid/histogram-window-v1"
_ENTROPY_SCHEMA = "climate-grid/entropy-window-v1"
_WEIGHTED_HISTOGRAM_SCHEMA = "climate-grid/weighted-histogram-window-v1"
_WEIGHTED_ENTROPY_SCHEMA = "climate-grid/weighted-entropy-window-v1"
_EXCEEDANCE_SCHEMA = "climate-grid/exceedance-window-v1"
_COVERAGE_SCHEMA = "climate-grid/coverage-window-v1"
_MULTI_COVERAGE_SCHEMA = "climate-grid/multi-coverage-window-v1"
_MULTI_EXCEEDANCE_SCHEMA = "climate-grid/multi-exceedance-window-v1"
_VARIANCE_SCHEMA = "climate-grid/variance-window-v1"
_MULTI_VARIANCE_SCHEMA = "climate-grid/multi-variance-window-v1"
_WEIGHTED_MULTI_VARIANCE_SCHEMA = "climate-grid/weighted-multi-variance-window-v1"
_SKEWNESS_SCHEMA = "climate-grid/skewness-window-v1"
_KURTOSIS_SCHEMA = "climate-grid/kurtosis-window-v1"
_MULTI_SKEW_SCHEMA = "climate-grid/multi-skew-v1"
_MULTI_KURTOSIS_SCHEMA = "climate-grid/multi-kurtosis-v1"
_TREND_SCHEMA = "climate-grid/trend-window-v1"
_WEIGHTED_TREND_SCHEMA = "climate-grid/weighted-trend-window-v1"
_CORRELATION_SCHEMA = "climate-grid/correlation-window-v1"
_MULTI_CORRELATION_SCHEMA = "climate-grid/multi-correlation-window-v1"
_WEIGHTED_CORRELATION_SCHEMA = "climate-grid/weighted-correlation-window-v1"
_AUTOCORRELATION_SCHEMA = "climate-grid/autocorrelation-window-v1"
_WEIGHTED_AUTOCORRELATION_SCHEMA = "climate-grid/weighted-autocorrelation-window-v1"
_REGRESSION_SCHEMA = "climate-grid/regression-window-v1"
_WEIGHTED_REGRESSION_SCHEMA = "climate-grid/weighted-regression-window-v1"
_CHANGE_SCHEMA = "climate-grid/change-window-v1"
_MULTI_CHANGE_SCHEMA = "climate-grid/multi-change-window-v1"
_WEIGHTED_MULTI_CHANGE_SCHEMA = "climate-grid/weighted-multi-change-window-v1"
_MULTI_AUTOCORR_SCHEMA = "climate-grid/multi-ac-v1"
_WEIGHTED_MULTI_AUTOCORR_SCHEMA = "climate-grid/weighted-multi-ac-v1"
_MULTI_QUANTILE_SCHEMA = "climate-grid/multi-quantile-window-v1"
_WEIGHTED_MULTI_QUANTILE_SCHEMA = "climate-grid/weighted-multi-quantile-window-v1"
_MULTI_ENTROPY_SCHEMA = "climate-grid/multi-entropy-window-v1"
_WEIGHTED_MULTI_ENTROPY_SCHEMA = "climate-grid/weighted-multi-entropy-window-v1"
_TEMPORAL_SCHEMA = "climate-grid/temporal-v1"
_TEMPORAL_KEYS = frozenset({"schema", "times", "lats", "lons", "data"})
_SERIES_KEYS = frozenset({"values", "status", "uncertainty"})
_STATUSES = frozenset({"observed", "interpolated", "missing"})
_REGION_KEYS = frozenset({"name", "cells"})
_WINDOW_KEYS = frozenset({"name", "start", "end"})
_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")


def _round_output(value: float) -> float:
    value = round(value, 12)
    if value == 0.0:
        # Normalize negative zero.
        return 0.0
    return value


def _parse_date(value: Any, where: str) -> datetime.date:
    if not isinstance(value, str):
        raise TypeError(f"{where} must be a str")
    if _DATE_RE.fullmatch(value) is None:
        raise ValueError(f"{where} must be a YYYY-MM-DD date")
    year, month, day = (int(part) for part in value.split("-"))
    try:
        return datetime.date(year, month, day)
    except ValueError:
        raise ValueError(f"{where} must be a valid Gregorian date") from None


def _validate_axis(axis: Any, name: str) -> None:
    if not isinstance(axis, list):
        raise TypeError(f"{name} must be a list")
    if len(axis) == 0:
        raise ValueError(f"{name} must be non-empty")
    for index, value in enumerate(axis):
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError(
                f"{name}[{index}] must be a finite non-bool int or float"
            )
        if not math.isfinite(value):
            raise ValueError(f"{name}[{index}] must be finite")
    for index in range(1, len(axis)):
        if axis[index] <= axis[index - 1]:
            raise ValueError(f"{name} must be strictly increasing")


def _validate_number(cell: Any, target: str) -> None:
    if cell is None:
        return
    if not isinstance(cell, (int, float)) or isinstance(cell, bool):
        raise TypeError(f"{target} must be a number or None")
    if not math.isfinite(cell):
        raise ValueError(f"{target} must be finite")


def _validate_member(
    member: Any, n_times: int, n_lat: int, n_lon: int, name: str, kind: str
) -> None:
    if not isinstance(member, list):
        raise TypeError(f"{name} must be a list")
    if len(member) != n_times:
        raise ValueError(f"{name} must have {n_times} frames (one per time)")
    for t, frame in enumerate(member):
        frame_where = f"{name}[{t}]"
        if not isinstance(frame, list):
            raise TypeError(f"{frame_where} must be a list")
        if len(frame) != n_lat:
            raise ValueError(f"{frame_where} must have {n_lat} rows (one per lat)")
        for i, row in enumerate(frame):
            row_where = f"{frame_where}[{i}]"
            if not isinstance(row, list):
                raise TypeError(f"{row_where} must be a list")
            if len(row) != n_lon:
                raise ValueError(
                    f"{row_where} must have {n_lon} cells (one per lon)"
                )
            for j, cell in enumerate(row):
                target = f"{row_where}[{j}]"
                if kind == "status":
                    if not isinstance(cell, str):
                        raise TypeError(f"{target} must be a str")
                    if cell not in _STATUSES:
                        raise ValueError(
                            f"{target} must be one of observed, interpolated, missing"
                        )
                else:
                    _validate_number(cell, target)


def _validate_series(
    series: dict, n_times: int, n_lat: int, n_lon: int, where: str
) -> None:
    for member in ("values", "status", "uncertainty"):
        _validate_member(
            series[member], n_times, n_lat, n_lon, f"{where}.{member}", member
        )
    values = series["values"]
    status = series["status"]
    uncertainty = series["uncertainty"]
    for t in range(n_times):
        for i in range(n_lat):
            for j in range(n_lon):
                target = f"{where}[{t}][{i}][{j}]"
                if status[t][i][j] == "missing":
                    if values[t][i][j] is not None:
                        raise ValueError(
                            f"{target}: missing cells must have a None value"
                        )
                    if uncertainty[t][i][j] is not None:
                        raise ValueError(
                            f"{target}: missing cells must have a None uncertainty"
                        )
                else:
                    if values[t][i][j] is None:
                        raise ValueError(
                            f"{target}: non-missing cells must have a value"
                        )
                    if uncertainty[t][i][j] is None:
                        raise ValueError(
                            f"{target}: non-missing cells must have an uncertainty"
                        )


def _validate_temporal(temporal: Any) -> tuple[list, list, list, dict]:
    if not isinstance(temporal, dict):
        raise TypeError("temporal must be a dict")
    if set(temporal.keys()) != _TEMPORAL_KEYS:
        raise ValueError(
            "temporal must have exactly the keys schema, times, lats, lons, data"
        )
    if not isinstance(temporal["schema"], str):
        raise TypeError("temporal.schema must be a str")
    if temporal["schema"] != _TEMPORAL_SCHEMA:
        raise ValueError(f"temporal.schema must be {_TEMPORAL_SCHEMA!r}")

    times = temporal["times"]
    if not isinstance(times, list):
        raise TypeError("temporal.times must be a list")
    if len(times) == 0:
        raise ValueError("temporal.times must be non-empty")
    days = [
        _parse_date(value, f"temporal.times[{index}]")
        for index, value in enumerate(times)
    ]
    for index in range(1, len(days)):
        if (days[index] - days[index - 1]).days != 1:
            raise ValueError(
                "temporal.times must be strictly increasing consecutive days"
            )

    lats = temporal["lats"]
    lons = temporal["lons"]
    _validate_axis(lats, "temporal.lats")
    _validate_axis(lons, "temporal.lons")

    data = temporal["data"]
    if not isinstance(data, dict):
        raise TypeError("temporal.data must be a dict")
    if len(data) == 0:
        raise ValueError("temporal.data must be non-empty")

    n_times = len(times)
    n_lat = len(lats)
    n_lon = len(lons)
    for element, series in data.items():
        if not isinstance(element, str):
            raise TypeError("temporal.data element names must be str")
        if element == "":
            raise ValueError("temporal.data element names must be non-empty")
        where = f"temporal.data[{element!r}]"
        if not isinstance(series, dict):
            raise TypeError(f"{where} must be a dict")
        if set(series.keys()) != _SERIES_KEYS:
            raise ValueError(
                f"{where} must have exactly the keys values, status, uncertainty"
            )
        _validate_series(series, n_times, n_lat, n_lon, where)

    return times, lats, lons, data


def _validate_regions(
    regions: Any, n_lat: int, n_lon: int
) -> list[tuple[str, list[tuple[int, int]]]]:
    if not isinstance(regions, list):
        raise TypeError("regions must be a list")
    if len(regions) == 0:
        raise ValueError("regions must be non-empty")

    validated: list[tuple[str, list[tuple[int, int]]]] = []
    seen_names: set[str] = set()
    for r_index, region in enumerate(regions):
        where = f"regions[{r_index}]"
        if not isinstance(region, dict):
            raise TypeError(f"{where} must be a dict")
        if set(region.keys()) != _REGION_KEYS:
            raise ValueError(f"{where} must have exactly the keys name, cells")

        name = region["name"]
        if not isinstance(name, str):
            raise TypeError(f"{where}.name must be a str")
        if name == "":
            raise ValueError(f"{where}.name must be non-empty")
        if name in seen_names:
            raise ValueError(f"duplicate region name: {name!r}")
        seen_names.add(name)

        cells = region["cells"]
        if not isinstance(cells, list):
            raise TypeError(f"{where}.cells must be a list")
        if len(cells) == 0:
            raise ValueError(f"{where}.cells must be non-empty")

        parsed_cells: list[tuple[int, int]] = []
        previous: tuple[int, int] | None = None
        for c_index, cell in enumerate(cells):
            target = f"{where}.cells[{c_index}]"
            if not isinstance(cell, list):
                raise TypeError(f"{target} must be a list")
            if len(cell) != 2:
                raise ValueError(f"{target} must have exactly two items [i, j]")
            for axis, coordinate in enumerate(cell):
                label = "i" if axis == 0 else "j"
                if not isinstance(coordinate, int) or isinstance(coordinate, bool):
                    raise TypeError(f"{target}.{label} must be a non-bool int")
                if coordinate < 0:
                    raise ValueError(f"{target}.{label} must be non-negative")
                limit = n_lat if axis == 0 else n_lon
                if coordinate >= limit:
                    raise ValueError(
                        f"{target}.{label} must be within the grid "
                        f"(0 <= {label} < {limit})"
                    )
            pair = (cell[0], cell[1])
            if previous is not None and pair <= previous:
                raise ValueError(
                    f"{where}.cells must be strictly ascending and unique"
                )
            previous = pair
            parsed_cells.append(pair)

        validated.append((name, parsed_cells))

    return validated


def _region_series(
    values: list,
    status: list,
    uncertainty: list,
    cells: list[tuple[int, int]],
    n_times: int,
    min_count: int,
) -> dict:
    counts: list[int] = []
    means: list[float | None] = []
    mins: list[float | None] = []
    maxs: list[float | None] = []
    uncertainties: list[float | None] = []

    for t in range(n_times):
        day_values = [
            values[t][i][j] for i, j in cells if status[t][i][j] != "missing"
        ]
        count = len(day_values)
        counts.append(count)
        if count < min_count:
            means.append(None)
            mins.append(None)
            maxs.append(None)
            uncertainties.append(None)
            continue

        day_uncertainties = [
            uncertainty[t][i][j]
            for i, j in cells
            if status[t][i][j] != "missing"
        ]
        means.append(_round_output(sum(day_values) / count))
        mins.append(_round_output(min(day_values)))
        maxs.append(_round_output(max(day_values)))
        uncertainties.append(
            _round_output(
                math.sqrt(sum(u ** 2 for u in day_uncertainties)) / count
            )
        )

    return {
        "count": counts,
        "mean": means,
        "min": mins,
        "max": maxs,
        "uncertainty": uncertainties,
    }


def _validate_windows(
    windows: Any, times: list
) -> list[tuple[str, str, str, int, int]]:
    if not isinstance(windows, list):
        raise TypeError("windows must be a list")
    if len(windows) == 0:
        raise ValueError("windows must be non-empty")

    day_index = {day: index for index, day in enumerate(times)}
    validated: list[tuple[str, str, str, int, int]] = []
    seen_names: set[str] = set()
    for w_index, window in enumerate(windows):
        where = f"windows[{w_index}]"
        if not isinstance(window, dict):
            raise TypeError(f"{where} must be a dict")
        if list(window.keys()) != ["name", "start", "end"]:
            raise ValueError(
                f"{where} must have exactly the keys name, start, end in order"
            )

        name = window["name"]
        if not isinstance(name, str):
            raise TypeError(f"{where}.name must be a str")
        if name == "":
            raise ValueError(f"{where}.name must be non-empty")
        if name in seen_names:
            raise ValueError(f"duplicate window name: {name!r}")
        seen_names.add(name)

        start = window["start"]
        end = window["end"]
        start_day = _parse_date(start, f"{where}.start")
        end_day = _parse_date(end, f"{where}.end")
        if start not in day_index:
            raise ValueError(f"{where}.start must be within temporal.times")
        if end not in day_index:
            raise ValueError(f"{where}.end must be within temporal.times")
        if start_day > end_day:
            raise ValueError(f"{where}.start must be on or before {where}.end")

        validated.append((name, start, end, day_index[start], day_index[end]))

    return validated


def _validate_weights(
    weights: Any, regions: list[tuple[str, list[tuple[int, int]]]]
) -> list[list[float]]:
    if not isinstance(weights, list):
        raise TypeError("weights must be a list")
    if len(weights) == 0:
        raise ValueError("weights must be non-empty")
    if len(weights) != len(regions):
        raise ValueError("weights must have one entry per region")

    validated: list[list[float]] = []
    for w_index, entry in enumerate(weights):
        where = f"weights[{w_index}]"
        if not isinstance(entry, dict):
            raise TypeError(f"{where} must be a dict")
        if list(entry.keys()) != ["name", "values"]:
            raise ValueError(
                f"{where} must have exactly the keys name, values in order"
            )

        name = entry["name"]
        if not isinstance(name, str):
            raise TypeError(f"{where}.name must be a str")
        if name == "":
            raise ValueError(f"{where}.name must be non-empty")
        expected_name = regions[w_index][0]
        if name != expected_name:
            raise ValueError(
                f"{where}.name must match regions[{w_index}].name "
                f"({expected_name!r})"
            )

        values = entry["values"]
        if not isinstance(values, list):
            raise TypeError(f"{where}.values must be a list")
        expected_len = len(regions[w_index][1])
        if len(values) != expected_len:
            raise ValueError(
                f"{where}.values must have {expected_len} weights (one per cell)"
            )

        validated_values: list[float] = []
        for v_index, weight in enumerate(values):
            target = f"{where}.values[{v_index}]"
            if not isinstance(weight, (int, float)) or isinstance(weight, bool):
                raise TypeError(
                    f"{target} must be a finite non-bool int or float"
                )
            if not math.isfinite(weight):
                raise ValueError(f"{target} must be finite")
            if weight <= 0:
                raise ValueError(f"{target} must be positive")
            validated_values.append(weight)
        validated.append(validated_values)

    return validated


def _window_region(
    values: list,
    status: list,
    uncertainty: list,
    cells: list[tuple[int, int]],
    t_start: int,
    t_end: int,
    min_count: int,
) -> dict:
    window_values: list[float] = []
    window_uncertainties: list[float] = []
    for t in range(t_start, t_end + 1):
        for i, j in cells:
            if status[t][i][j] != "missing":
                window_values.append(values[t][i][j])
                window_uncertainties.append(uncertainty[t][i][j])

    count = len(window_values)
    if count < min_count:
        return {
            "count": count,
            "mean": None,
            "min": None,
            "max": None,
            "uncertainty": None,
        }

    return {
        "count": count,
        "mean": _round_output(sum(window_values) / count),
        "min": _round_output(min(window_values)),
        "max": _round_output(max(window_values)),
        "uncertainty": _round_output(
            math.sqrt(sum(u ** 2 for u in window_uncertainties)) / count
        ),
    }


def _weighted_window_region(
    values: list,
    status: list,
    uncertainty: list,
    cells: list[tuple[int, int]],
    weights: list[float],
    t_start: int,
    t_end: int,
    min_count: int,
) -> dict:
    window_weights: list[float] = []
    window_values: list[float] = []
    window_uncertainties: list[float] = []
    for t in range(t_start, t_end + 1):
        for cell_index, (i, j) in enumerate(cells):
            if status[t][i][j] != "missing":
                window_weights.append(weights[cell_index])
                window_values.append(values[t][i][j])
                window_uncertainties.append(uncertainty[t][i][j])

    count = len(window_values)
    if count < min_count:
        return {
            "count": count,
            "mean": None,
            "min": None,
            "max": None,
            "uncertainty": None,
        }

    weight_sum = sum(window_weights)
    return {
        "count": count,
