        return {
            "count": count,
            "bin_counts": bin_counts,
            "rates": [None for _ in range(n_bins)],
            "uncertainty": None,
        }

    return {
        "count": count,
        "bin_counts": bin_counts,
        "rates": [_round_output(bin_count / count) for bin_count in bin_counts],
        "uncertainty": _round_output(math.sqrt(uncertainty_sq_sum) / count),
